// Imagine each block is its own .js module.

// math.js  -> named exports
const mathModule = (() => {
  const PI = 3.14159;
  function add(a, b) { return a + b; }
  return { PI, add }; // export { PI, add }
})();

// User.js  -> default export
const UserModule = (() => {
  class User { constructor(name) { this.name = name; } }
  return { default: User }; // export default User
})();

// app.js  -> imports
const { PI, add } = mathModule;        // import { PI, add } from './math.js'
const User = UserModule.default;        // import User from './User.js'

console.log(add(2, 3)); // 5
console.log(PI);        // 3.14159
console.log(new User('Ada').name); // Ada

