solution.code:
const cartModule = (() => {
  const items = []; // private to the module scope
  const TAX_RATE = 0.1;
  function addItem(item) { items.push(item); }
  function total() {
    const sub = items.reduce((s, i) => s + i.price, 0);
    return sub + sub * TAX_RATE;
  }
  return { TAX_RATE, addItem, total }; // export { TAX_RATE, addItem, total }
})();

const { TAX_RATE, addItem, total } = cartModule;
addItem({ name: 'pen', price: 10 });
addItem({ name: 'pad', price: 20 });
console.log(TAX_RATE);
console.log(total());

